import{_ as t,o as s,c as o,a3 as i}from"./chunks/framework.BlfGB29P.js";const r="/images/logic-studio/user-guide/blocks-js-fr.png",h=JSON.parse('{"title":"Blocks JS","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/logic-studio/user-guide/blocks-js.md","filePath":"fr/projects/logic-studio/user-guide/blocks-js.md","lastUpdated":1795433064000}'),a={name:"fr/projects/logic-studio/user-guide/blocks-js.md"};function n(l,e,c,u,d,p){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="blocks-js" tabindex="-1">Blocks JS <a class="header-anchor" href="#blocks-js" aria-label="Permalink to &quot;Blocks JS&quot;">​</a></h1><h2 id="premier-exemple" tabindex="-1">Premier exemple <a class="header-anchor" href="#premier-exemple" aria-label="Permalink to &quot;Premier exemple&quot;">​</a></h2><p>Le test lit l’état simulé d’une entité et l’affiche dans le journal.</p><ol><li>Choisis <strong>Nouveau projet → Blocks JS</strong>. Dans <strong>Système</strong>, glisse le bloc <strong>Journal</strong> sur le canevas.</li><li>Glisse <strong>État de</strong> dans l’entrée libre du bloc de journal. Choisis ton entité de test. La capture utilise <code>binary_sensor.bewegung</code>.</li><li>Lance un <strong>test</strong> et consulte le <strong>journal</strong>. La démonstration affiche l’état et le message <code>on</code>. Le script lit et affiche la valeur.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-js-fr.png"><img src="'+r+'" alt="Blocks JS avec un bloc d’état relié au journal"></a></p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><h3 id="systeme-actions-et-sendto" tabindex="-1">Système, actions et Sendto <a class="header-anchor" href="#systeme-actions-et-sendto" aria-label="Permalink to &quot;Système, actions et Sendto&quot;">​</a></h3><p>Lis des états, commande des cibles autorisées, envoie des messages ou consulte l’historique. Une entrée dynamique peut accepter un identifiant obtenu dans une boucle.</p><h3 id="declencheurs-temps-et-temporisations" tabindex="-1">Déclencheurs, temps et temporisations <a class="header-anchor" href="#declencheurs-temps-et-temporisations" aria-label="Permalink to &quot;Déclencheurs, temps et temporisations&quot;">​</a></h3><p>Démarre sur changement d’état, événement solaire ou horaire. Utilise des règles CRON simples ou nommées, des délais, des intervalles et leurs blocs d’arrêt.</p><h3 id="blocs-de-valeurs" tabindex="-1">Blocs de valeurs <a class="header-anchor" href="#blocs-de-valeurs" aria-label="Permalink to &quot;Blocs de valeurs&quot;">​</a></h3><p>Les catégories conversion, objet, logique, mathématiques, texte, listes et couleur produisent des valeurs. Les boucles répètent des opérations.</p><h3 id="variables-et-fonctions" tabindex="-1">Variables et fonctions <a class="header-anchor" href="#variables-et-fonctions" aria-label="Permalink to &quot;Variables et fonctions&quot;">​</a></h3><p>Les variables conservent des valeurs intermédiaires. Les fonctions regroupent des étapes et peuvent renvoyer une valeur.</p><h3 id="import-iobroker" tabindex="-1">Import ioBroker <a class="header-anchor" href="#import-iobroker" aria-label="Permalink to &quot;Import ioBroker&quot;">​</a></h3><p>Colle l’export en mode expert et lis le rapport. Associe explicitement les entités et consulte les indications de chaque bloc.</p><h3 id="verifier-si-un-id-iobroker-calcule-existe" tabindex="-1">Vérifier si un ID ioBroker calculé existe <a class="header-anchor" href="#verifier-si-un-id-iobroker-calcule-existe" aria-label="Permalink to &quot;Vérifier si un ID ioBroker calculé existe&quot;">​</a></h3><p>Si ton script ioBroker construit un ID à partir de plusieurs fragments de texte, utilise le bloc importé <code>state_exists_var</code> pour le vérifier.</p><ol><li>Dans la vérification de l’import, saisis l’ID ioBroker calculé complet et l’ID d’entité HA correspondant dans <strong>Correspondance des ID (JSON)</strong>, par exemple <code>{&quot;0_userdata.0.jardin.pompe&quot;:&quot;switch.pompe_jardin&quot;}</code>. Ce champ est aussi disponible dans le bloc importé.</li><li>Autorise l’entité associée dans <code>runtime_read_entities</code> dans les réglages de l’application si elle ne dispose pas encore d’une autorisation d’écriture.</li><li>Enregistre le projet et clique sur <strong>Play</strong>. Une entité HA existante renvoie <code>true</code>. Une entité associée mais absente renvoie <code>false</code>. Si aucune association n’existe pour l’ID calculé, l’exécution s’arrête et le journal indique cet ID. Ajoute l’association dans le bloc, puis relance le projet.</li></ol><h3 id="importer-un-point-de-donnees-iobroker-comme-assistant-ha" tabindex="-1">Importer un point de données ioBroker comme assistant HA <a class="header-anchor" href="#importer-un-point-de-donnees-iobroker-comme-assistant-ha" aria-label="Permalink to &quot;Importer un point de données ioBroker comme assistant HA&quot;">​</a></h3><p>Si ton export Blockly contient le bloc de création d’un point de données (<code>createState</code>), tu peux stocker sa valeur dans un assistant Home Assistant. L’assistant apparaît dans <strong>Paramètres → Appareils et services → Assistants</strong>.</p><ol><li>Dans les outils experts, ouvre l’import ioBroker, colle l’export et vérifie l’importation.</li><li>Choisis l’une des trois options pour l’identifiant ioBroker : <ul><li><strong>Associer un assistant</strong> utilise un assistant existant et conserve sa valeur actuelle.</li><li><strong>Créer un assistant</strong> propose un interrupteur, un assistant numérique ou un assistant texte selon le type de données. Vérifie et confirme le nom. La création nécessite un compte administrateur HA. Une valeur initiale fixe compatible est appliquée une seule fois. Pour une valeur initiale calculée, tu peux préparer un assistant dans HA puis l’associer.</li><li><strong>Associer plus tard</strong> laisse l’association en attente. Ouvre le projet et sélectionne une entité HA compatible dans le bloc importé avant de lancer le script.</li></ul></li><li>Vérifie que les blocs de création, de lecture et de mise à jour du même identifiant ioBroker utilisent la même entité HA. Ouvre l’import comme projet et enregistre-le.</li><li>Autorise l’assistant dans les options de l’application sous <code>runtime_read_entities</code> et, pour les mises à jour, sous <code>runtime_write_entities</code>. Lance le script enregistré avec <strong>Play</strong>. Le script lit la valeur actuelle de l’assistant, y compris après une modification dans Home Assistant.</li></ol><p>L’exemple crée un assistant numérique avec <strong>17</strong>. Au premier lancement, le script journalise <strong>17</strong> et écrit <strong>42</strong>. Après le redémarrage du script, le journal affiche <strong>42</strong>. Tu peux ainsi vérifier que la valeur initiale a été appliquée uniquement à la création de l’assistant. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/ha-logic-studio-pro-v0.1.122/ha_logic_studio_pro/tests/fixtures/iobroker-create-state.xml" target="_blank" rel="noreferrer">Exemple Blockly</a></p><h3 id="blocs-http-importes" tabindex="-1">Blocs HTTP importés <a class="header-anchor" href="#blocs-http-importes" aria-label="Permalink to &quot;Blocs HTTP importés&quot;">​</a></h3><p>Choisis une commande REST HA autorisée. Configure l’URL, le délai et les en-têtes dans HA. Le bloc POST indique le Content-Type importé.</p><h3 id="test-et-play" tabindex="-1">Test et Play <a class="header-anchor" href="#test-et-play" aria-label="Permalink to &quot;Test et Play&quot;">​</a></h3><p>Commence par la simulation. Enregistre avant Play et vérifie les résultats réels dans le journal.</p><h2 id="verifier-un-import-etape-par-etape" tabindex="-1">Vérifier un import étape par étape <a class="header-anchor" href="#verifier-un-import-etape-par-etape" aria-label="Permalink to &quot;Vérifier un import étape par étape&quot;">​</a></h2><ol><li>Active le <strong>mode expert</strong> dans le menu du projet. Dans l’éditeur, ouvre les outils experts et choisis l’import ioBroker.</li><li>Colle le XML Blockly ou un export JavaScript ioBroker contenant les données Blockly. Vérifie l’import et repère les blocs à associer.</li><li>Ouvre l’import comme projet et suis les indications affichées sur les blocs concernés. Pour un POST importé, choisis la commande REST HA qui définit les en-têtes et le délai.</li><li>Enregistre et lance d’abord un <strong>test</strong>. Utilise ensuite <strong>Play</strong> pour l’exécution réelle, vérifie le <strong>journal</strong> et termine avec <strong>Stop</strong>.</li></ol><h2 id="en-cas-de-probleme" tabindex="-1">En cas de problème <a class="header-anchor" href="#en-cas-de-probleme" aria-label="Permalink to &quot;En cas de problème&quot;">​</a></h2><p>Adapte les blocs signalés avant l’exécution.</p>',31)])])}const b=t(a,[["render",n]]);export{h as __pageData,b as default};
